const state={user:null,nodes:[],dashboard:null,currentNode:null,currentContainer:null,currentFilter:'all',lastLogContainer:null,adminUsers:[],accessResources:null,accessUser:null,accessConfig:null,alertRules:[],scalingServices:[],pendingImage:null,profileTab:'account',scalingTabs:{}};
const $=(s,root=document)=>root.querySelector(s);const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=(v)=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const roleName={admin:'管理员',operator:'运维',viewer:'只读'};let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function cookie(name){return document.cookie.split('; ').find(row=>row.startsWith(`${name}=`))?.split('=').slice(1).join('=')||''}
async function api(path,options={}){const method=(options.method||'GET').toUpperCase();const headers={'Content-Type':'application/json',...(options.headers||{})};if(['POST','PUT','PATCH','DELETE'].includes(method))headers['X-CSRF-Token']=decodeURIComponent(cookie('__Host-cloudhelm_csrf'));const response=await fetch(`/api/v1${path}`,{...options,method,headers,credentials:'same-origin'});if(response.status===401){showLogin();throw new Error('登录已过期，请从企业微信重新进入')}if(!response.ok){let detail=`请求失败 (${response.status})`;try{detail=(await response.json()).detail||detail}catch{}throw new Error(detail)}if(response.status===204)return null;return response.json()}
function greeting(){const hour=new Date().getHours();return hour<6?'夜深了':hour<11?'早上好':hour<14?'中午好':hour<18?'下午好':'晚上好'}
function showLogin(){state.user=null;$('#app-view').classList.add('hidden');$('#login-view').classList.remove('hidden')}
function showApp(){$('#login-view').classList.add('hidden');$('#app-view').classList.remove('hidden');$('#display-name').textContent=state.user.display_name;$('#profile-name').textContent=state.user.display_name;$('#profile-role').textContent=`${roleName[state.user.role]||state.user.role}${state.user.role!=='admin'&&state.user.can_manage_access?' · 资源管理员':''}`;$('#profile-avatar').textContent=state.user.display_name.slice(0,1);$('#avatar-button').textContent=state.user.display_name.slice(0,1);$('#greeting').textContent=greeting();$('#admin-users').classList.toggle('hidden',!state.user.can_manage_access);$('#admin-alert-rules').classList.toggle('hidden',state.user.role!=='admin');$('#admin-scaling').classList.toggle('hidden',state.user.role!=='admin');$('[data-profile-tab="users"]').classList.toggle('hidden',!state.user.can_manage_access);$('[data-profile-tab="alerts"]').classList.toggle('hidden',state.user.role!=='admin');$('[data-profile-tab="scaling"]').classList.toggle('hidden',state.user.role!=='admin');$('#add-user-button').classList.toggle('hidden',state.user.role!=='admin');selectProfileTab('account');if(state.user.can_manage_access)loadUsers();if(state.user.role==='admin'){loadAlertRules();loadScaling()}navigate('overview');refreshAll()}
async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}showLogin()}
async function restore(){try{state.user=await api('/auth/me');showApp()}catch{showLogin()}}
function inWecom(){return /wxwork/i.test(navigator.userAgent)}
$('#login-form').addEventListener('submit',e=>{e.preventDefault();window.location.assign(inWecom()?'/api/v1/auth/wecom/start':'/api/v1/auth/wecom/qr/start')});
function navigate(name){$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));$$('.tab-bar button').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));if(name==='audit'){loadAlerts();loadAudit()}window.scrollTo({top:0,behavior:'smooth'})}
function selectProfileTab(name){const allowed=name==='account'||(name==='users'&&state.user?.can_manage_access)||(['alerts','scaling'].includes(name)&&state.user?.role==='admin');state.profileTab=allowed?name:'account';$$('[data-profile-tab]').forEach(button=>button.classList.toggle('active',button.dataset.profileTab===state.profileTab));$$('[data-profile-panel]').forEach(panel=>panel.classList.toggle('profile-tab-hidden',panel.dataset.profilePanel!==state.profileTab));if(state.profileTab==='users')loadUsers();if(state.profileTab==='alerts')loadAlertRules();if(state.profileTab==='scaling')loadScaling();window.scrollTo({top:0,behavior:'smooth'})}
$$('[data-nav]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.nav)));$('#avatar-button').addEventListener('click',()=>navigate('profile'));$('#logout-button').addEventListener('click',logout);$('#refresh-button').addEventListener('click',async()=>{await refreshAll();toast('状态已刷新')});
$$('[data-profile-tab]').forEach(button=>button.addEventListener('click',()=>selectProfileTab(button.dataset.profileTab)));
async function refreshAll(){try{const [dashboard,nodes]=await Promise.all([api('/dashboard'),api('/nodes')]);state.dashboard=dashboard;state.nodes=nodes;renderDashboard();renderNodes();renderFilters();if(state.user?.role==='admin')loadScaling()}catch(err){toast(err.message)}}
function renderDashboard(){const d=state.dashboard,system=d.system||{},business=d.business||{};$('#online-nodes').textContent=d.nodes.online;$('#node-caption').textContent=`共 ${d.nodes.total} 台 · ${d.nodes.offline} 台离线`;$('#running-containers').textContent=d.containers.running;$('#stopped-containers').textContent=d.containers.stopped;$('#gpu-count').textContent=d.gpus?.total??0;$('#gpu-summary').textContent=d.gpus?.total?`平均负载 ${Number(d.gpus.average_utilization).toFixed(1)}%`:'NVIDIA GPU';$('#host-network-rate').textContent=system.node_count?`↓ ${formatRate(system.network_rx_bps)} · ↑ ${formatRate(system.network_tx_bps)}`:'—';$('#host-disk-usage').textContent=system.disk_total_bytes?`${(system.disk_used_bytes/system.disk_total_bytes*100).toFixed(1)}%`:'—';$('#active-businesses').textContent=business.active??0;$('#business-summary').textContent=`${business.instances??0} 个上报实例`;const badge=$('#fleet-status');badge.classList.toggle('online',d.nodes.online>0);$('span',badge).textContent=d.nodes.offline?'存在离线节点':'舰队运行正常'}
function gpuAverage(items){const values=(items||[]).map(g=>g.utilization_gpu).filter(v=>v!==null&&v!==undefined);return values.length?values.reduce((a,b)=>a+Number(b),0)/values.length:null}
function nodeCard(n){const last=n.last_seen_at?new Date(n.last_seen_at).toLocaleString('zh-CN',{hour12:false}):'从未上报';const gpuAvg=gpuAverage(n.gpus);const gpuText=n.gpus?.length?`${n.gpus.length} · ${gpuAvg===null?'—':gpuAvg.toFixed(0)+'%'}`:'—';const system=n.system_metrics||{},disk=system.disk_total_bytes?`${(system.disk_used_bytes/system.disk_total_bytes*100).toFixed(1)}%`:'—',network=n.system_metrics_status==='ok'?`↓${formatRate(system.network_rx_bps)} ↑${formatRate(system.network_tx_bps)}`:'—';return `<article class="node-card" data-node="${esc(n.id)}"><div class="node-top"><div class="node-identity"><span class="node-icon ${n.online?'':'offline'}">${n.online?'⌁':'—'}</span><div><strong>${esc(n.name)}</strong><span>${esc(n.hostname||'未报告主机名')}</span></div></div><span class="status-pill ${n.online?'':'offline'}">${n.online?'在线':'离线'}</span></div><div class="node-stats gpu-aware"><div><span>容器</span><strong>${n.running_count} / ${n.container_count}</strong></div><div><span>GPU</span><strong class="gpu-node-summary">${esc(gpuText)}</strong></div><div><span>网络</span><strong>${esc(network)}</strong></div><div><span>磁盘</span><strong>${esc(disk)}</strong></div><div><span>环境</span><strong>${esc(n.environment)}</strong></div><div><span>最后心跳</span><strong>${esc(last)}</strong></div></div></article>`}
function bindNodes(root){$$('[data-node]',root).forEach(card=>card.addEventListener('click',()=>openNode(card.dataset.node)))}
function renderNodes(){const preview=state.nodes.slice(0,4);$('#overview-nodes').classList.remove('skeleton-list');$('#overview-nodes').innerHTML=preview.length?preview.map(nodeCard).join(''):'<div class="empty">还没有节点，请部署 Agent 并完成注册。</div>';bindNodes($('#overview-nodes'));const q=$('#node-search').value.trim().toLowerCase();const filtered=state.nodes.filter(n=>(state.currentFilter==='all'||n.environment===state.currentFilter)&&(!q||`${n.name} ${n.hostname} ${n.environment}`.toLowerCase().includes(q)));$('#all-nodes').innerHTML=filtered.length?filtered.map(nodeCard).join(''):'<div class="empty">没有符合条件的节点。</div>';bindNodes($('#all-nodes'))}
function renderFilters(){const envs=[...new Set(state.nodes.map(n=>n.environment))];$('#environment-filters').innerHTML=[['all','全部'],...envs.map(e=>[e,e])].map(([key,label])=>`<button data-filter="${esc(key)}" class="${state.currentFilter===key?'active':''}">${esc(label)}</button>`).join('');$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.currentFilter=b.dataset.filter;renderFilters();renderNodes()}))}
$('#node-search').addEventListener('input',renderNodes);
function metric(value,suffix='',digits=0){return value===null||value===undefined?'—':`${Number(value).toFixed(digits)}${suffix}`}
function renderNodeGpus(node){const root=$('#node-gpus');const gpus=node.gpus||[];if(['error','unavailable'].includes(node.gpu_status)&&node.gpu_error){root.classList.remove('hidden');root.innerHTML=`<div class="gpu-warning">GPU 监控${node.gpu_status==='error'?'异常':'不可用'}：${esc(node.gpu_error)}</div>`;return}if(!gpus.length){root.classList.add('hidden');root.innerHTML='';return}root.classList.remove('hidden');const updated=node.gpu_updated_at?new Date(node.gpu_updated_at).toLocaleTimeString('zh-CN',{hour12:false}):'—',baseline=Number(node.gpu_expected_count??gpus.length),reset=state.user?.role==='admin'?'<button class="gpu-baseline-button" data-reset-gpu-baseline>重设 GPU 基线</button>':'';root.innerHTML=`<div class="gpu-section-head"><h2>NVIDIA GPU</h2><span>更新于 ${esc(updated)} · 基线 ${baseline} 张</span>${reset}</div><div class="gpu-grid">${gpus.map(g=>{const used=g.memory_used_mib??0,total=g.memory_total_mib??0,pct=total?Math.min(100,used/total*100):0;return `<article class="gpu-card"><div class="gpu-card-head"><div><strong>${esc(g.name)}</strong><span>${esc(g.uuid)}</span></div><b class="gpu-index">GPU ${g.index}${g.mig_mode?` · MIG ${esc(g.mig_mode)}`:''}</b></div><div class="gpu-primary"><div><span>GPU 使用率</span><strong>${metric(g.utilization_gpu,'%',1)}</strong></div><div><span>显存</span><strong>${metric(used,' MiB')} / ${metric(total,' MiB')}</strong><progress class="gpu-memory-bar" value="${pct.toFixed(1)}" max="100" aria-label="显存使用率"></progress></div></div><div class="gpu-secondary"><div><span>温度</span><strong>${metric(g.temperature_c,'°C',0)}</strong></div><div><span>功耗</span><strong>${metric(g.power_draw_w,' W',1)}${g.power_limit_w?` / ${metric(g.power_limit_w,' W',0)}`:''}</strong></div><div><span>驱动 / CUDA</span><strong>${esc(g.driver_version||'—')} / ${esc(g.cuda_version||'—')}</strong></div></div></article>`}).join('')}</div>`;const button=$('[data-reset-gpu-baseline]',root);if(button)button.addEventListener('click',async()=>{if(!window.confirm(`确认将 ${node.name} 当前 ${gpus.length} 张 GPU 设为新的掉卡检测基线？`))return;button.disabled=true;try{const result=await api(`/nodes/${node.id}/gpu-baseline/reset`,{method:'POST'});node.gpu_expected_count=result.gpu_expected_count;toast('GPU 基线已更新');renderNodeGpus(node)}catch(err){toast(err.message)}finally{button.disabled=false}})}
function renderNodeTitle(node){const root=$('#container-node-title'),gateway=node.gateway_address||'未配置';root.innerHTML=`<p class="eyebrow">${esc(node.environment)} · ${node.online?'ONLINE':'OFFLINE'}</p><h1>${esc(node.name)}</h1><p>${esc(node.hostname)} · Docker ${esc(node.docker_version)} · 网关访问 IP ${esc(gateway)}</p>${state.user?.role==='admin'?'<button data-node-gateway-address>配置网关访问 IP</button>':''}`;const button=$('[data-node-gateway-address]',root);if(button)button.addEventListener('click',()=>updateNodeGatewayAddress(node))}
async function updateNodeGatewayAddress(node){const value=window.prompt('填写统一网关访问这台节点上业务容器时使用的 IPv4/IPv6；留空将清除配置。',node.gateway_address||'');if(value===null)return;try{const result=await api(`/nodes/${node.id}/gateway-address`,{method:'PUT',body:JSON.stringify({gateway_address:value.trim()||null})});node.gateway_address=result.gateway_address;renderNodeTitle(node);toast(result.gateway_address?'网关访问 IP 已保存':'网关访问 IP 已清除')}catch(err){toast(err.message)}}
async function openNode(id){const node=state.nodes.find(n=>n.id===id);if(!node)return;state.currentNode=node;navigate('containers');renderNodeTitle(node);renderNodeSystem(node);renderNodeInterfaces(node);if(node.system_metrics_status==='restricted'){$('#node-history').classList.add('hidden');$('#node-history').innerHTML=''}else renderNodeHistory(id);renderNodeGpus(node);$('#project-groups').innerHTML='<div class="skeleton"></div>';try{const containers=await api(`/nodes/${id}/containers`);renderContainers(containers)}catch(err){toast(err.message)}}
$('#containers-back').addEventListener('click',()=>navigate('nodes'));
function renderContainers(items){const groups={};items.forEach(c=>{const key=c.compose_project||'独立容器';(groups[key]??=[]).push(c)});const root=$('#project-groups');root.innerHTML=Object.entries(groups).length?Object.entries(groups).map(([name,list])=>`<section class="project-block"><h2 class="project-name">${esc(name)}</h2><div class="container-list">${list.map(containerCard).join('')}</div></section>`).join(''):'<div class="empty">此节点暂未上报容器。</div>';$$('[data-container]',root).forEach(el=>el.addEventListener('click',()=>openContainer(el.dataset.container)))}
function formatBytes(bytes){if(!bytes)return'0 B';const units=['B','KB','MB','GB','TB'];const i=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),4);return`${(bytes/1024**i).toFixed(i>1?1:0)} ${units[i]}`}
function formatRate(bytes){return`${formatBytes(bytes)}/s`}
function formatDuration(seconds){const value=Number(seconds||0),days=Math.floor(value/86400),hours=Math.floor(value%86400/3600);return days?`${days} 天 ${hours} 小时`:`${hours} 小时`}
function renderNodeSystem(node){const root=$('#node-system'),system=node.system_metrics||{};if(node.system_metrics_status==='restricted'){root.classList.add('hidden');root.innerHTML='';return}if(node.system_metrics_status!=='ok'){root.classList.remove('hidden');root.innerHTML=`<div class="monitor-warning">主机监控不可用：${esc(node.system_metrics_error||'等待新版 Agent 上报')}</div>`;return}const total=Number(system.disk_total_bytes||0),used=Number(system.disk_used_bytes||0),percent=total?Math.min(100,used/total*100):0,inodeTotal=Number(system.disk_inodes_total||0),inodeUsed=Number(system.disk_inodes_used||0),inodePercent=inodeTotal?Math.min(100,inodeUsed/inodeTotal*100):0,updated=node.system_metrics_updated_at?new Date(node.system_metrics_updated_at).toLocaleTimeString('zh-CN',{hour12:false}):'—',alerts=[];if(percent>=90)alerts.push(`根磁盘已使用 ${percent.toFixed(1)}%`);if(inodePercent>=90)alerts.push(`inode 已使用 ${inodePercent.toFixed(1)}%`);if(Number(system.memory_percent)>=90)alerts.push(`内存已使用 ${Number(system.memory_percent).toFixed(1)}%`);root.classList.remove('hidden');root.innerHTML=`<div class="system-section-head"><h2>主机资源</h2><span>更新于 ${esc(updated)}</span></div>${alerts.length?`<div class="monitor-warning critical">${alerts.map(esc).join('；')}</div>`:''}<div class="system-grid"><article><span>CPU / 系统负载</span><strong>${metric(system.cpu_percent,'%',1)}</strong><small>${metric(system.load_1,'',2)} / ${metric(system.load_5,'',2)} / ${metric(system.load_15,'',2)}</small></article><article><span>内存 / Swap</span><strong>${formatBytes(system.memory_used_bytes)} / ${formatBytes(system.memory_total_bytes)}</strong><small>${metric(system.memory_percent,'%',1)} · Swap ${formatBytes(system.swap_used_bytes)}</small></article><article><span>网络接收</span><strong>↓ ${formatRate(system.network_rx_bps)}</strong><small>累计 ${formatBytes(system.network_rx_bytes)}</small></article><article><span>网络发送</span><strong>↑ ${formatRate(system.network_tx_bps)}</strong><small>累计 ${formatBytes(system.network_tx_bytes)}</small></article><article><span>运行时间</span><strong>${formatDuration(system.uptime_seconds)}</strong><small>接口 ${esc((system.network_interfaces||[]).join(', ')||'—')}</small></article><article><span>inode</span><strong>${inodePercent.toFixed(1)}%</strong><small>${inodeUsed.toLocaleString()} / ${inodeTotal.toLocaleString()}</small></article><article class="system-disk"><span>根磁盘</span><strong>${formatBytes(used)} / ${formatBytes(total)}</strong><small>可用 ${formatBytes(system.disk_free_bytes)} · ${percent.toFixed(1)}%</small><progress value="${percent.toFixed(1)}" max="100" aria-label="根磁盘使用率"></progress></article></div>`}
function renderNodeInterfaces(node){const root=$('#node-interfaces'),system=node.system_metrics||{},items=system.network_interface_metrics||[];if(node.system_metrics_status!=='ok'){root.classList.add('hidden');root.innerHTML='';return}root.classList.remove('hidden');if(!items.length){root.innerHTML='<div class="monitor-warning">没有发现处于 UP 状态且配置了可用 IP 的监控网卡。</div>';return}root.innerHTML=`<div class="system-section-head"><h2>主机网卡</h2><span>${items.length} 张 · 汇总值写入历史</span></div><div class="interface-grid">${items.map(item=>`<article><header><strong>${esc(item.name)}</strong><span>${esc((item.addresses||[]).join(' · ')||'—')}</span></header><div><span>实时</span><strong>↓ ${formatRate(item.rx_bps)} · ↑ ${formatRate(item.tx_bps)}</strong></div><small>累计 ↓ ${formatBytes(item.rx_bytes)} · ↑ ${formatBytes(item.tx_bytes)}</small></article>`).join('')}</div>`}
function sparkline(samples,key,color='#22bfa8',percent=false){const values=samples.map(item=>Number(item[key]||0)),width=260,height=58;if(values.length<2)return'<div class="history-empty">正在积累历史数据…</div>';const maximum=percent?100:Math.max(...values,1),minimum=percent?0:Math.min(...values),range=Math.max(maximum-minimum,1),points=values.map((value,index)=>`${(index/(values.length-1)*width).toFixed(1)},${(height-(value-minimum)/range*(height-6)-3).toFixed(1)}`).join(' ');return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function historyCard(title,samples,key,formatter,color,percent=false){const latest=samples.length?samples[samples.length-1][key]:0;return `<article><header><span>${esc(title)}</span><strong>${esc(formatter(latest))}</strong></header>${sparkline(samples,key,color,percent)}</article>`}
function businessHistoryCard(samples){const latest=samples.length?samples[samples.length-1]:{};return `<article class="business-history-card"><header><span>业务负载</span><strong>${Number(latest.active_businesses||0)} 单 / 容量 ${Number(latest.business_capacity||0)}</strong></header>${sparkline(samples,'active_businesses','#e16a43')}</article>`}
async function renderNodeHistory(nodeId){const root=$('#node-history');root.classList.remove('hidden');root.innerHTML='<div class="skeleton"></div>';try{const samples=await api(`/nodes/${nodeId}/metrics/history?hours=24&limit=1000`);root.innerHTML=`<div class="system-section-head"><h2>最近 24 小时</h2><span>每 5 分钟采样 · ${samples.length} 点</span></div><div class="history-grid">${businessHistoryCard(samples)}${historyCard('CPU',samples,'cpu_percent',value=>`${Number(value).toFixed(1)}%`,'#25a78f',true)}${historyCard('内存',samples,'memory_percent',value=>`${Number(value).toFixed(1)}%`,'#6d51d8',true)}${historyCard('网络接收',samples,'network_rx_bps',formatRate,'#2d9ff0')}${historyCard('根磁盘',samples,'disk_used_bytes',formatBytes,'#e49a36')}</div>`}catch(err){root.innerHTML=`<div class="monitor-warning">历史指标读取失败：${esc(err.message)}</div>`}}
async function renderContainerHistory(containerId){const root=$('#container-history');if(!root)return;try{const samples=await api(`/containers/${containerId}/metrics/history?hours=24&limit=1000`);root.innerHTML=`<div class="system-section-head"><h2>最近 24 小时</h2><span>定频采样 · ${samples.length} 点</span></div><div class="history-grid">${historyCard('CPU',samples,'cpu_percent',value=>`${Number(value).toFixed(1)}%`,'#25a78f',true)}${historyCard('内存',samples,'memory_percent',value=>`${Number(value).toFixed(1)}%`,'#6d51d8',true)}${historyCard('网络接收',samples,'network_rx_bps',formatRate,'#2d9ff0')}${historyCard('磁盘写入',samples,'block_write_bps',formatRate,'#e49a36')}</div>`}catch(err){root.innerHTML=`<div class="monitor-warning">历史指标读取失败：${esc(err.message)}</div>`}}
function gpuAllocation(c){if(c.gpu_all)return'全部 GPU';return c.gpu_devices?.length?c.gpu_devices.join(', '):''}
function containerCard(c){const gpu=gpuAllocation(c),alerts=[c.oom_killed?'OOM':null,c.health==='unhealthy'?'健康检查失败':null,c.status==='restarting'?'反复重启':null].filter(Boolean),loads=c.business_loads||[],active=loads.reduce((sum,item)=>sum+Number(item.active_businesses||0),0),capacity=loads.reduce((sum,item)=>sum+Number(item.capacity_limit||0),0);return `<article class="container-card ${alerts.length?'has-alert':''}" data-container="${esc(c.id)}"><i class="container-state ${c.status==='running'?'running':''}"></i><div class="container-main"><strong>${esc(c.name)}</strong><span>${esc(c.image||'unknown image')}</span>${alerts.map(item=>`<b class="alert-label">${esc(item)}</b>`).join('')}${gpu?`<b class="gpu-allocation">GPU ${esc(gpu)}</b>`:''}${loads.length?`<b class="gpu-allocation">业务 ${active} / ${capacity}</b>`:''}</div><div class="container-resource"><strong>CPU ${Number(c.cpu_percent).toFixed(1)}%</strong><span>RAM ${formatBytes(c.memory_usage)}</span><span>↓${formatRate(c.network_rx_bps)} ↑${formatRate(c.network_tx_bps)}</span><span>磁盘 ${formatBytes(c.writable_layer_bytes)}</span></div></article>`}
async function openContainer(id){try{const c=await api(`/containers/${id}`);state.currentContainer=c;const running=c.status==='running';const permissions=c.permissions||{};const actions=[];const gpu=gpuAllocation(c);const assigned=c.assigned_gpus||[];const gpuMetrics=assigned.length?`<div class="container-gpu-metrics"><h3>已分配 GPU 当前状态（整卡）</h3>${assigned.map(g=>`<div><strong>GPU ${g.index} · ${esc(g.name)}</strong><span>负载 ${metric(g.utilization_gpu,'%',1)} · 显存 ${metric(g.memory_used_mib,' MiB')} / ${metric(g.memory_total_mib,' MiB')} · ${metric(g.temperature_c,'°C',0)}</span></div>`).join('')}</div>`:'';if(permissions.logs)actions.push('<button data-action="logs">查看日志</button>');if(permissions.operate){actions.push(`<button class="primary" data-action="${running?'restart':'start'}">${running?'重启':'启动'}</button>`);actions.push(running?'<button class="danger" data-action="stop">停止</button>':'<button disabled>已停止</button>')}if(permissions.update_image)actions.push('<button class="image-action" data-action="update_image">更换 Tag</button>');const actionHtml=actions.length?actions.join(''):'<span class="scope-note">当前授权仅允许查看状态</span>',alerts=[c.oom_killed?'容器发生过 OOM Kill':null,c.health==='unhealthy'?`健康检查失败 ${c.health_failing_streak||0} 次`:null,c.status==='restarting'?'容器正在反复重启':null].filter(Boolean),alertHtml=alerts.length?`<div class="monitor-warning critical">${alerts.map(esc).join('；')}</div>`:'';$('#container-detail').innerHTML=`<div class="detail-head"><span class="status-pill ${running?'':'offline'}">${esc(c.status)}${c.health?` · ${esc(c.health)}`:''}</span><h2>${esc(c.name)}</h2><p>${esc(c.node_name)} / ${esc(c.compose_project||'独立容器')}</p></div>${alertHtml}<div class="detail-grid"><div><span>CPU 使用率</span><strong>${Number(c.cpu_percent).toFixed(2)}%</strong></div><div><span>内存</span><strong>${formatBytes(c.memory_usage)}</strong></div><div><span>网络接收</span><strong>↓ ${formatRate(c.network_rx_bps)}</strong></div><div><span>网络发送</span><strong>↑ ${formatRate(c.network_tx_bps)}</strong></div><div><span>磁盘读取</span><strong>↓ ${formatRate(c.block_read_bps)}</strong></div><div><span>磁盘写入</span><strong>↑ ${formatRate(c.block_write_bps)}</strong></div><div><span>PID / 重启次数</span><strong>${Number(c.pids||0)} / ${Number(c.restart_count||0)}</strong></div><div><span>可写层磁盘</span><strong>${formatBytes(c.writable_layer_bytes)}</strong></div><div><span>镜像 + 可写层</span><strong>${formatBytes(c.rootfs_bytes)}</strong></div><div><span>内存占比</span><strong>${Number(c.memory_percent).toFixed(2)}%</strong></div><div><span>状态更新时间</span><strong>${new Date(c.updated_at).toLocaleTimeString('zh-CN',{hour12:false})}</strong></div></div><div class="detail-meta"><div><span>累计网络接收 / 发送</span><strong>↓ ${formatBytes(c.network_rx_bytes)} / ↑ ${formatBytes(c.network_tx_bytes)}</strong></div><div><span>累计磁盘读取 / 写入</span><strong>↓ ${formatBytes(c.block_read_bytes)} / ↑ ${formatBytes(c.block_write_bytes)}</strong></div>${!running?`<div><span>退出码 / 结束时间</span><strong>${c.exit_code??'—'} / ${esc(c.finished_at||'—')}</strong></div>`:''}<div><span>镜像</span><strong>${esc(c.image||'—')}</strong></div><div><span>Compose 服务</span><strong>${esc(c.compose_service||'—')}</strong></div><div><span>GPU 分配</span><strong class="gpu-detail-value">${esc(gpu||'未分配')}</strong></div><div><span>容器 ID</span><strong>${esc(c.docker_id.slice(0,12))}</strong></div></div><section id="container-history" class="metrics-history"><div class="skeleton"></div></section>${gpuMetrics}<div class="action-grid">${actionHtml}</div>`;$$('[data-action]',$('#container-detail')).forEach(b=>b.addEventListener('click',()=>requestAction(b.dataset.action)));$('#container-sheet').classList.remove('hidden');renderContainerHistory(id)}catch(err){toast(err.message)}}
function closeSheet(){$('#container-sheet').classList.add('hidden')}$$('[data-close-sheet]').forEach(b=>b.addEventListener('click',closeSheet));$('#container-sheet').addEventListener('click',e=>{if(e.target.id==='container-sheet')closeSheet()});
function requestAction(action){if(action==='logs')return showLogs();if(action==='update_image')return openImageDialog();const names={restart:'重启',start:'启动',stop:'停止'};$('#confirm-title').textContent=`确认${names[action]}容器？`;$('#confirm-copy').textContent=`${state.currentNode.name} / ${state.currentContainer.name}\n操作会被记录到审计日志。`;$('#confirm-dialog').classList.remove('hidden');$('#confirm-action').onclick=()=>executeAction(action)}
$$('[data-cancel]').forEach(b=>b.addEventListener('click',()=>$('#confirm-dialog').classList.add('hidden')));
async function executeAction(action){$('#confirm-dialog').classList.add('hidden');try{const task=await api(`/containers/${state.currentContainer.id}/actions`,{method:'POST',body:JSON.stringify({action})});toast('任务已下发');const result=await waitTask(task.id);if(result.status==='success'){toast('操作成功');closeSheet();setTimeout(()=>openNode(state.currentNode.id),600)}else throw new Error(result.error||'Agent 执行失败')}catch(err){toast(err.message)}}
function splitTaggedImage(image){if(!image||image.includes('@'))return null;const slash=image.lastIndexOf('/'),colon=image.lastIndexOf(':');if(colon<=slash)return null;return{repository:image.slice(0,colon),tag:image.slice(colon+1)}}
function openImageDialog(){const current=splitTaggedImage(state.currentContainer?.image);if(!current){toast('当前镜像没有明确 Tag，无法在线替换');return}state.pendingImage=null;$('#image-repository').value=current.repository;$('#image-current-tag').value=current.tag;$('#image-target-tag').value='';$('#image-form-error').textContent='';$('#image-dialog').classList.remove('hidden');setTimeout(()=>$('#image-target-tag').focus(),50)}
$$('[data-close-image]').forEach(button=>button.addEventListener('click',()=>$('#image-dialog').classList.add('hidden')));
$('#image-form').addEventListener('submit',event=>{event.preventDefault();const repository=$('#image-repository').value,targetTag=$('#image-target-tag').value.trim(),currentTag=$('#image-current-tag').value;if(!/^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$/.test(targetTag)){$('#image-form-error').textContent='Tag 格式无效';return}if(targetTag===currentTag){$('#image-form-error').textContent='新旧 Tag 不能相同';return}state.pendingImage={current:state.currentContainer.image,target:`${repository}:${targetTag}`};$('#image-dialog').classList.add('hidden');$('#confirm-title').textContent='再次确认替换镜像？';$('#confirm-copy').textContent=`容器：${state.currentContainer.name}\n原镜像：${state.pendingImage.current}\n新镜像：${state.pendingImage.target}\n\nAgent 将拉取镜像并重建容器，失败时自动恢复旧容器。`;$('#confirm-action').onclick=executeImageUpdate;$('#confirm-dialog').classList.remove('hidden')});
async function executeImageUpdate(){const change=state.pendingImage;if(!change)return;$('#confirm-dialog').classList.add('hidden');try{toast('正在拉取镜像并替换容器…');const task=await api(`/containers/${state.currentContainer.id}/actions`,{method:'POST',body:JSON.stringify({action:'update_image',target_image:change.target})});const result=await waitTask(task.id,180);if(result.status!=='success')throw new Error(result.error||'Agent 更新镜像失败');toast('镜像 Tag 已更新');closeSheet();await refreshAll();setTimeout(()=>openNode(state.currentNode.id),800)}catch(err){toast(err.message)}finally{state.pendingImage=null}}
async function waitTask(id,attempts=35){for(let i=0;i<attempts;i++){const task=await api(`/tasks/${id}`);if(['success','failed','expired'].includes(task.status))return task;await new Promise(r=>setTimeout(r,1000))}throw new Error('Agent 响应超时，请稍后查看审计记录')}
async function showLogs(){state.lastLogContainer=state.currentContainer;$('#logs-title').textContent=state.currentContainer.name;$('#logs-content').textContent='正在向 Agent 请求最近 200 行日志…';$('#logs-status').textContent='等待 Agent 返回';$('#logs-dialog').classList.remove('hidden');await loadLogs()}
async function loadLogs(){const c=state.lastLogContainer;if(!c)return;try{const task=await api(`/containers/${c.id}/actions`,{method:'POST',body:JSON.stringify({action:'logs',tail:200})});const result=await waitTask(task.id);if(result.status!=='success')throw new Error(result.error||'日志读取失败');$('#logs-content').textContent=result.result||'（日志为空）';$('#logs-status').textContent=`更新于 ${new Date().toLocaleTimeString('zh-CN',{hour12:false})}`}catch(err){$('#logs-content').textContent=`读取失败：${err.message}`;$('#logs-status').textContent='读取失败'}}
$$('[data-close-logs]').forEach(b=>b.addEventListener('click',()=>$('#logs-dialog').classList.add('hidden')));$('#logs-refresh').addEventListener('click',loadLogs);
async function loadAudit(){const root=$('#audit-list');root.innerHTML='<div class="skeleton"></div>';try{const items=await api('/audit?limit=100');root.innerHTML=items.length?items.map(a=>`<article class="audit-item ${a.success?'':'failed'}"><div class="audit-title"><strong>${esc(a.username_label||a.username)} · ${esc(a.action_label||a.action)} · ${a.success?'成功':'失败'}</strong><time>${new Date(a.created_at).toLocaleString('zh-CN',{hour12:false})}</time></div><p>${esc(a.target_type_label||a.target_type)}：${esc(a.target_name||'—')}${(a.detail_label||a.detail)?` · ${esc(a.detail_label||a.detail)}`:''}</p></article>`).join(''):'<div class="empty">暂无审计记录。</div>'}catch(err){root.innerHTML=`<div class="empty">${esc(err.message)}</div>`}}
async function loadAlerts(){const root=$('#alert-event-list');root.innerHTML='<div class="skeleton"></div>';try{const items=await api('/alerts/events?limit=100');root.innerHTML=items.length?items.map(item=>`<article class="alert-event ${esc(item.severity)} ${item.active?'active':''}"><div><strong>${esc(item.rule_name)} · ${esc(item.target_name)}</strong><span>${esc(item.message)}</span><small>${new Date(item.created_at).toLocaleString('zh-CN',{hour12:false})} · ${item.active?'当前仍异常':item.status==='recovered'?'已恢复':'历史事件'}${item.notified?' · 已通知':''}${item.notification_error?' · 通知失败':''}</small></div>${item.can_acknowledge&&!item.acknowledged?`<button data-ack-alert="${esc(item.id)}">确认</button>`:`<b>${item.acknowledged?'已确认':item.status==='recovered'?'恢复':'待处理'}</b>`}</article>`).join(''):'<div class="empty">暂无告警事件。</div>';$$('[data-ack-alert]',root).forEach(button=>button.addEventListener('click',async()=>{try{await api(`/alerts/events/${button.dataset.ackAlert}/acknowledge`,{method:'POST'});toast('告警已确认');loadAlerts()}catch(err){toast(err.message)}}))}catch(err){root.innerHTML=`<div class="empty">${esc(err.message)}</div>`}}
const alertMetricNames={node_offline:'节点离线秒数',node_cpu_percent:'节点 CPU',node_memory_percent:'节点内存',node_disk_percent:'节点根磁盘',node_inode_percent:'节点 inode',container_cpu_percent:'容器 CPU',container_memory_percent:'容器内存',container_unhealthy:'健康检查异常',container_oom_killed:'OOM Kill',container_restarting:'反复重启',node_gpu_utilization_percent:'GPU 使用率',node_gpu_memory_percent:'GPU 显存使用率',node_gpu_temperature_c:'GPU 温度',node_gpu_missing:'GPU 掉卡或监控异常',node_network_surge_percent:'节点网络流量突增',container_disk_growth_mibps:'容器可写层增长 MiB/s',container_exit_abnormal:'容器异常退出',node_load_percent:'宿主机负载率',node_swap_percent:'宿主机 Swap',node_metrics_unavailable:'宿主机指标采集失效'};
async function loadAlertRules(){if(state.user?.role!=='admin')return;const root=$('#alert-rule-list');root.innerHTML='<div class="skeleton"></div>';try{state.alertRules=await api('/alerts/rules');root.innerHTML=state.alertRules.map(rule=>`<article class="alert-rule" data-alert-rule="${esc(rule.id)}"><div class="alert-rule-title"><strong>${esc(rule.name)}</strong><span>${esc(alertMetricNames[rule.metric]||rule.metric)} · ${esc(rule.scope_type)}</span></div><label>阈值<input data-alert-threshold type="number" step="0.1" value="${Number(rule.threshold)}"></label><label>连续次数<input data-alert-consecutive type="number" min="1" max="100" value="${Number(rule.consecutive_required)}"></label><label class="alert-switch"><input data-alert-enabled type="checkbox" ${rule.enabled?'checked':''}>启用</label><label class="alert-switch"><input data-alert-notify type="checkbox" ${rule.notify?'checked':''}>通知</label><div class="alert-rule-actions"><button data-test-alert>模拟</button><button data-save-alert>保存</button></div></article>`).join('')||'<div class="empty">暂无告警规则。</div>';$$('[data-save-alert]',root).forEach(button=>button.addEventListener('click',()=>saveAlertRule(button.closest('[data-alert-rule]'))));$$('[data-test-alert]',root).forEach(button=>button.addEventListener('click',()=>sendTestAlert(button.closest('[data-alert-rule]'))))}catch(err){root.innerHTML=`<div class="empty">${esc(err.message)}</div>`}}
async function saveAlertRule(row){const rule=state.alertRules.find(item=>item.id===row.dataset.alertRule);if(!rule)return;const payload={...rule,threshold:Number($('[data-alert-threshold]',row).value),consecutive_required:Number($('[data-alert-consecutive]',row).value),enabled:$('[data-alert-enabled]',row).checked,notify:$('[data-alert-notify]',row).checked};delete payload.id;delete payload.updated_at;try{await api(`/alerts/rules/${rule.id}`,{method:'PUT',body:JSON.stringify(payload)});toast('告警规则已保存');loadAlertRules()}catch(err){toast(err.message)}}
async function sendTestAlert(row){const rule=state.alertRules.find(item=>item.id===row.dataset.alertRule);if(!rule||!window.confirm(`确认模拟“${rule.name}”？\n\n系统会按这条规则的范围选取一个资源，并像真实告警一样通知所有符合权限和订阅条件的成员。`))return;const button=$('[data-test-alert]',row);button.disabled=true;try{const result=await api(`/alerts/rules/${rule.id}/notification/test`,{method:'POST'});toast(`模拟告警已发送给 ${result.recipient_count} 人`);window.alert(`${result.message}\n\n模拟资源：${result.target_name}\n接收人（${result.recipient_count}）：${result.recipient_names.join('、')}`);loadAudit()}catch(err){toast(err.message);loadAudit()}finally{button.disabled=false}}
$('#refresh-alerts').addEventListener('click',loadAlerts);$('#refresh-alert-rules').addEventListener('click',loadAlertRules);
async function loadUsers(){if(!state.user?.can_manage_access)return;try{const users=await api('/users');state.adminUsers=users;$('#user-list').innerHTML=users.map(u=>`<article class="user-item"><div><strong>${esc(u.display_name)}</strong><span>企微 ${esc(u.wecom_userid)} · ${u.is_active?'已启用':'已停用'} · ${u.role==='admin'?'始终全部资源':u.resource_restricted?'自定义范围':'全部资源'}${u.resource_admin_count?` · ${u.resource_admin_count} 条管理授权`:''}${u.global_alert_notifications?' · 全部可见资源告警':u.alert_subscription_count?` · ${u.alert_subscription_count} 条告警订阅`:''}</span></div><div class="user-actions"><b>${esc(roleName[u.role]||u.role)}</b>${u.can_edit_account?`<button class="scope-button" data-revoke-user="${esc(u.id)}">下线</button><button class="scope-button" data-toggle-user="${esc(u.id)}">${u.is_active?'停用':'启用'}</button>${u.resource_admin_count?`<button class="scope-button danger-text" data-revoke-management="${esc(u.id)}">撤销管理权</button>`:''}`:''}${u.can_edit_access?`<button class="scope-button" data-access-user="${esc(u.id)}">权限与告警</button>`:''}</div></article>`).join('');$$('[data-access-user]').forEach(button=>button.addEventListener('click',()=>openAccess(button.dataset.accessUser)));$$('[data-revoke-user]').forEach(button=>button.addEventListener('click',()=>revokeUserSessions(button.dataset.revokeUser)));$$('[data-toggle-user]').forEach(button=>button.addEventListener('click',()=>toggleUser(button.dataset.toggleUser)));$$('[data-revoke-management]').forEach(button=>button.addEventListener('click',()=>revokeManagement(button.dataset.revokeManagement)))}catch(err){toast(err.message)}}
async function revokeManagement(userId){const user=state.adminUsers.find(item=>item.id===userId);if(!user||!window.confirm(`确认撤销 ${user.display_name} 的全部资源管理权？\n\n查看、日志和运维权限将保留，此操作会记录审计日志。`))return;try{await api(`/users/${userId}/access/management`,{method:'DELETE'});toast('资源管理权已撤销');loadUsers()}catch(err){toast(err.message)}}
async function revokeUserSessions(userId){try{await api(`/users/${userId}/sessions/revoke`,{method:'POST'});toast('该用户的登录会话已撤销')}catch(err){toast(err.message)}}
async function toggleUser(userId){const user=state.adminUsers.find(item=>item.id===userId);if(!user)return;try{await api(`/users/${userId}`,{method:'PATCH',body:JSON.stringify({is_active:!user.is_active})});toast(user.is_active?'账号已停用':'账号已启用');loadUsers()}catch(err){toast(err.message)}}
const newUserRole=$('#user-form [name="role"]'),newUserAccessMode=$('#new-user-access-mode');
function syncNewUserAccess(){const admin=newUserRole.value==='admin';if(admin)newUserAccessMode.value='global';newUserAccessMode.disabled=admin;const restricted=!admin&&newUserAccessMode.value==='restricted';$('#new-user-access-hint').textContent=admin?'管理员始终拥有全部资源，不需要单独绑定容器。':restricted?'创建账号后继续选择可见环境、节点、Compose 项目或具体容器。':'该角色可以访问当前及以后上报的全部资源。';$('#create-user-label').textContent=restricted?'下一步：绑定容器':'创建账号'}
newUserRole.addEventListener('change',syncNewUserAccess);newUserAccessMode.addEventListener('change',syncNewUserAccess);
$('#add-user-button').addEventListener('click',()=>{$('#user-form').reset();newUserAccessMode.disabled=false;syncNewUserAccess();$('#user-form-error').textContent='';$('#user-dialog').classList.remove('hidden');if(!state.accessResources)api('/access/resources').then(resources=>{state.accessResources=resources}).catch(()=>{})});
$$('[data-close-user]').forEach(b=>b.addEventListener('click',()=>$('#user-dialog').classList.add('hidden')));
$('#user-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type="submit"]',e.currentTarget);button.disabled=true;const data=Object.fromEntries(new FormData(e.currentTarget));const accessMode=data.role==='admin'?'global':newUserAccessMode.value;delete data.access_mode;try{const created=await api('/users',{method:'POST',body:JSON.stringify(data)});$('#user-dialog').classList.add('hidden');if(data.role!=='admin'&&accessMode==='global'){try{await api(`/users/${created.id}/access`,{method:'PUT',body:JSON.stringify({restricted:false,rules:[]})})}catch(err){toast(`账号已创建，但全部资源设置失败：${err.message}`);await loadUsers();return}}await loadUsers();if(data.role!=='admin'&&accessMode==='restricted'){toast('账号已创建，请选择可见容器');await openAccess(created.id)}else toast('账号及资源范围已创建')}catch(err){$('#user-form-error').textContent=err.message;$('#user-dialog').classList.remove('hidden')}finally{button.disabled=false}});
const ruleKey=r=>[r.scope_type,r.environment||'',r.node_id||'',r.project||'',r.container_id||''].join('|');
const ruleLevel=r=>r.can_manage?'manage':r.can_operate?'operate':r.can_logs?'logs':'view';
function permissionOptions(role,selected){const options=[['view','仅查看'],['logs','查看 + 日志']];if(role==='operator')options.push(['operate','查看 + 日志 + 运维'],['manage','资源管理员']);return options.map(([value,label])=>`<option value="${value}" ${selected===value?'selected':''}>${label}</option>`).join('')}
function accessRow(rule,label,meta,depth,existing,role){const key=ruleKey(rule);const found=existing.get(key);const checked=Boolean(found);const editable=new Set(state.accessResources?.editable_scope_keys||[]).has(key);const attributes=`data-scope-type="${esc(rule.scope_type)}" data-environment="${esc(rule.environment||'')}" data-node-id="${esc(rule.node_id||'')}" data-project="${esc(rule.project||'')}" data-container-id="${esc(rule.container_id||'')}"`;return `<div class="access-row depth-${depth} ${checked?'selected':''} ${editable?'':'locked'}" ${attributes}><input type="checkbox" data-rule aria-label="授权 ${esc(label)}" ${checked?'checked':''} ${editable?'':'disabled'}/><div><strong>${esc(label)}</strong><span>${esc(meta)}${editable?'':' · 仅用于定位'}</span></div><select aria-label="${esc(label)} 权限" ${editable?'':'disabled'}>${permissionOptions(role,found?ruleLevel(found):'view')}</select><label class="alert-subscribe"><input type="checkbox" data-alert-notify ${found?.alert_notify?'checked':''} ${editable&&checked?'':'disabled'}/>企微告警</label></div>`}
function renderAccessTree(config){const existing=new Map(config.rules.map(rule=>[ruleKey(rule),rule]));const resources=state.accessResources;const rows=[];for(const environment of resources.environments){rows.push(`<h3 class="access-group-title">${esc(environment)} 环境</h3>`);rows.push(accessRow({scope_type:'environment',environment},environment,'授权该环境全部节点',0,existing,state.accessUser.role));for(const node of resources.nodes.filter(item=>item.environment===environment)){rows.push(accessRow({scope_type:'node',node_id:node.id},node.name,node.hostname||'节点',1,existing,state.accessUser.role));const projects=[...new Set(node.containers.map(item=>item.project||'独立容器'))];for(const project of projects){if(project!=='独立容器')rows.push(accessRow({scope_type:'project',node_id:node.id,project},project,'Compose 项目',2,existing,state.accessUser.role));for(const container of node.containers.filter(item=>(item.project||'独立容器')===project)){rows.push(accessRow({scope_type:'container',node_id:node.id,container_id:container.id},container.name,`${project} · ${container.status}`,3,existing,state.accessUser.role))}}}}$('#access-tree').innerHTML=rows.join('')||'<div class="empty">暂无可授权资源，请等待 Agent 上报。</div>';$$('[data-rule]',$('#access-tree')).forEach(input=>input.addEventListener('change',()=>{const row=input.closest('.access-row'),notify=$('[data-alert-notify]',row);row.classList.toggle('selected',input.checked);notify.disabled=!input.checked||input.disabled;if(!input.checked)notify.checked=false}))}
function syncAccessMode(){const admin=state.accessUser?.role==='admin',allowUnrestricted=Boolean(state.accessResources?.allow_unrestricted);if(admin)$('#access-mode').value='global';else if(!allowUnrestricted)$('#access-mode').value='restricted';$('#access-mode').disabled=admin||!allowUnrestricted;const restricted=$('#access-mode').value==='restricted';$('#access-tree').classList.toggle('hidden',!restricted);$('#global-alert-notify-row').classList.toggle('hidden',restricted);$('#access-hint').textContent=state.accessResources?.partial?'你只能修改自己管理范围内的授权；勾选“企微告警”可订阅该资源，其他授权会由服务端保留。':restricted?'仅勾选的资源可见；每个资源可独立订阅企微告警，“资源管理员”可继续授权。':'全部资源模式沿用账号角色权限；可统一订阅全部可见资源的企微告警。'}
async function openAccess(userId){state.accessUser=state.adminUsers.find(user=>user.id===userId);if(!state.accessUser)return;$('#access-title').textContent=`${state.accessUser.display_name} · 权限与告警`;$('#access-error').textContent='';$('#access-tree').innerHTML='<div class="skeleton"></div>';$('#access-dialog').classList.remove('hidden');try{const [config,resources]=await Promise.all([api(`/users/${userId}/access`),api('/access/resources')]);state.accessConfig=config;state.accessResources=resources;$('#access-mode').value=config.restricted?'restricted':'global';$('#global-alert-notify').checked=Boolean(config.global_alert_notify);renderAccessTree(config);syncAccessMode()}catch(err){$('#access-error').textContent=err.message}}
function accessPayload(){const restricted=$('#access-mode').value==='restricted';const rules=$$('.access-row',$('#access-tree')).filter(row=>!$('[data-rule]',row)?.disabled&&$('[data-rule]',row)?.checked).map(row=>{const level=$('select',row).value;return{scope_type:row.dataset.scopeType,environment:row.dataset.environment||null,node_id:row.dataset.nodeId||null,project:row.dataset.project||null,container_id:row.dataset.containerId||null,can_view:true,can_logs:['logs','operate','manage'].includes(level),can_operate:['operate','manage'].includes(level),can_manage:level==='manage',alert_notify:$('[data-alert-notify]',row).checked}});return{restricted,global_alert_notify:!restricted&&$('#global-alert-notify').checked,rules,expected_version:state.accessConfig?.version}}
$('#access-mode').addEventListener('change',syncAccessMode);$$('[data-close-access]').forEach(button=>button.addEventListener('click',()=>$('#access-dialog').classList.add('hidden')));$('#save-access-button').addEventListener('click',async()=>{if(!state.accessUser)return;const button=$('#save-access-button');button.disabled=true;$('#access-error').textContent='';const payload=accessPayload();try{const preview=await api(`/users/${state.accessUser.id}/access/preview`,{method:'POST',body:JSON.stringify(payload)}),summary=preview.summary;const changed=summary.added+summary.removed+summary.changed+(preview.restricted_changed?1:0)+(preview.global_alert_notify_changed?1:0);if(!changed){toast('权限和告警订阅没有变化');return}const warning=summary.management_elevations?`\n其中 ${summary.management_elevations} 项将授予资源管理权。`:'';const notifications=summary.notification_changes||preview.global_alert_notify_changed?`\n告警订阅调整 ${summary.notification_changes+(preview.global_alert_notify_changed?1:0)} 项。`:'';if(!window.confirm(`确认修改 ${state.accessUser.display_name} 的权限与告警订阅？\n\n新增 ${summary.added} 项，移除 ${summary.removed} 项，调整 ${summary.changed} 项。${warning}${notifications}\n\n操作会记录审计日志。`))return;const saved=await api(`/users/${state.accessUser.id}/access`,{method:'PUT',body:JSON.stringify(payload)});state.accessConfig.version=saved.version;$('#access-dialog').classList.add('hidden');toast('权限与告警订阅已保存');loadUsers()}catch(err){$('#access-error').textContent=err.message}finally{button.disabled=false}});
const scalingStatusNames={collecting:'积累 5 分钟窗口',monitoring:'仅监控',provider_disabled:'全局开关未启用',provider_error:'ACS 连接异常',stable:'容量稳定',cooldown:'冷却中',scaling_up:'正在扩容 ACS',scaling_up_failover:'本地故障，ACS 兜底',failover_active:'ACS 故障兜底中',draining:'ACS 实例排空中',scaling_down:'正在缩容 ACS',scale_down_waiting_for_reports:'等待 ACS 实例上报',at_minimum:'已到 ACS 最小副本',scale_failed:'伸缩失败'};
function scalingInput(name,label,value,type='number',extra=''){return `<label>${esc(label)}<input data-scale-field="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function renderScalingService(service){const status=scalingStatusNames[service.status]||service.status,error=service.last_error?` · ${service.last_error}`:'',active=state.scalingTabs[service.id]||'summary',panel=name=>`scaling-card-panel${active===name?'':' panel-hidden'}`,instances=(service.instances||[]).map(item=>{const gpu=item.pool==='local'?(item.gpu_names?.length?item.gpu_names.join(', '):item.gpu_all?'全部 GPU':item.gpu_devices?.length?`GPU ${item.gpu_devices.join(', ')}`:'未报告 GPU'):'ACS 资源',location=[item.node_name,item.container_name].filter(Boolean).join(' / ')||item.instance_id,endpoint=item.endpoint_host&&item.endpoint_scheme&&item.endpoint_port?`${item.endpoint_scheme}://${item.endpoint_host}:${Number(item.endpoint_port)}`:'尚未注册完整路由地址',inherited=item.capacity_limit===null||item.capacity_limit===undefined,deleteDisabled=item.container_id?'disabled title="已关联本地容器，不能删除"':'';return `<div class="scaling-instance" data-scaling-instance="${esc(item.id)}"><div class="scaling-instance-identity"><strong><b class="${esc(item.pool)}">${item.pool==='local'?'本地':'ACS'}</b> · ${esc(item.instance_id)}</strong><small>${esc(location)} · ${esc(gpu)} · ${esc(endpoint)}</small></div><span>${Number(item.active_businesses)} 单</span><span>${item.healthy&&item.ready&&item.accepting?'健康接单':'异常/排空'}</span><div class="capacity-effective"><b>${Number(item.effective_capacity)}</b><small class="capacity-inherited">${inherited?'继承默认':'实例覆盖'}</small></div><input data-instance-capacity type="number" min="1" placeholder="继承 ${Number(service.capacity_per_replica)}" value="${item.capacity_limit??''}" aria-label="${esc(item.instance_id)} 实例业务上限"><button data-save-instance-capacity>保存</button><button class="instance-delete" data-delete-instance ${deleteDisabled}>删除</button></div>`}).join('')||'<div class="empty">尚无实例上报；实例首次上报后会出现在这里。</div>';return `<article class="scaling-card" data-scaling-service="${esc(service.id)}"><div class="scaling-card-head"><div><strong>${esc(service.name)} · ${esc(service.service_type.toUpperCase())}</strong><span>服务 ID ${esc(service.id)} · ACS ${esc(service.namespace)}/${esc(service.workload_name)}${esc(error)}</span></div><b class="scaling-status ${service.last_error?'error':''}">${esc(status)}</b></div><nav class="scaling-card-tabs" aria-label="${esc(service.name)} 配置分页"><button class="${active==='summary'?'active':''}" data-scaling-tab="summary">运行概览</button><button class="${active==='instances'?'active':''}" data-scaling-tab="instances">实例容量</button><button class="${active==='policy'?'active':''}" data-scaling-tab="policy">伸缩策略</button><button class="${active==='release'?'active':''}" data-scaling-tab="release">镜像发布</button></nav><section class="${panel('summary')}" data-scaling-panel="summary"><div class="scaling-kpis"><div><span>当前 / 5 分钟均值</span><strong>${Number(service.current_businesses)} / ${Number(service.average_businesses).toFixed(1)}</strong></div><div><span>按实例容量计算的利用率</span><strong>${Number(service.utilization_percent).toFixed(1)}%</strong></div><div><span>上报实例</span><strong>${Number(service.reporting_instances)}</strong></div><div><span>ACS 副本</span><strong>${Number(service.current_replicas)} → ${Number(service.desired_replicas)}</strong></div></div></section><section class="${panel('policy')}" data-scaling-panel="policy"><div class="scaling-policy">${scalingInput('capacity_per_replica','新实例默认上限',service.capacity_per_replica)}${scalingInput('scale_up_threshold_percent','扩容阈值 %',service.scale_up_threshold_percent)}${scalingInput('scale_down_threshold_percent','缩容阈值 %',service.scale_down_threshold_percent)}${scalingInput('failover_replicas','故障兜底副本',service.failover_replicas)}${scalingInput('min_replicas','ACS 最小副本',service.min_replicas)}${scalingInput('max_replicas','ACS 最大副本',service.max_replicas)}${scalingInput('window_seconds','统计窗口 秒',service.window_seconds)}${scalingInput('cooldown_seconds','冷却时间 秒',service.cooldown_seconds)}${scalingInput('report_stale_seconds','上报失效 秒',service.report_stale_seconds)}<label class="wide">ACS 工作负载<input data-scale-field="workload_name" value="${esc(service.workload_name)}"></label><label>Namespace<input data-scale-field="namespace" value="${esc(service.namespace)}"></label><label>类型<select data-scale-field="workload_kind"><option ${service.workload_kind==='Deployment'?'selected':''}>Deployment</option><option ${service.workload_kind==='StatefulSet'?'selected':''}>StatefulSet</option></select></label><label class="scaling-checkbox wide"><input data-scale-enabled type="checkbox" ${service.autoscaling_enabled?'checked':''}>启用自动扩缩容</label><div class="scaling-policy-actions"><button data-rotate-scaling-token>轮换上报令牌</button><button data-save-scaling>保存策略</button></div></div></section><section class="${panel('instances')} scaling-instances" data-scaling-panel="instances"><h4>每个实例独立配置业务承载上限</h4><p class="scaling-capacity-note">不同显卡或模型配置可以设置不同上限。留空表示继承“新实例默认上限”；利用率按所有健康接单实例的生效容量之和计算。</p><div class="scaling-instance-head"><span>实例 / 节点 / GPU / 地址</span><span>负载</span><span>状态</span><span>生效上限</span><span>覆盖值</span><span>操作</span></div>${instances}</section></article>`}
async function loadScaling(){if(state.user?.role!=='admin')return;const root=$('#scaling-service-list');root.innerHTML='<div class="skeleton"></div>';try{const [services,events]=await Promise.all([api('/scaling/services'),api('/scaling/events?limit=30')]);state.scalingServices=services;root.innerHTML=services.map(renderScalingService).join('')||'<div class="empty">还没有混合云伸缩服务。</div>';bindScalingTabs(root);bindScalingInstanceMonitoring(root);bindScalingInstanceDeletion(root);bindScalingReleases(root);$('#scaling-event-list').innerHTML=events.map(item=>`<article class="scaling-event"><div><strong>${esc(item.service_name)} · ${esc(item.action)}</strong><span>${Number(item.from_replicas)} → ${Number(item.to_replicas)} · 利用率 ${Number(item.utilization_percent).toFixed(1)}%</span><small>${esc(item.detail)}</small></div><small>${new Date(item.created_at).toLocaleString('zh-CN',{hour12:false})}</small></article>`).join('')||'<div class="empty">暂无弹性事件。</div>';$$('[data-save-scaling]',root).forEach(button=>button.addEventListener('click',()=>saveScaling(button.closest('[data-scaling-service]'))));$$('[data-rotate-scaling-token]',root).forEach(button=>button.addEventListener('click',()=>rotateScalingToken(button.closest('[data-scaling-service]'))));$$('[data-save-instance-capacity]',root).forEach(button=>button.addEventListener('click',()=>saveInstanceCapacity(button.closest('[data-scaling-instance]'))))}catch(err){root.innerHTML=`<div class="empty">${esc(err.message)}</div>`}}
function bindScalingTabs(root){$$('[data-scaling-tab]',root).forEach(button=>button.addEventListener('click',()=>{const card=button.closest('[data-scaling-service]'),name=button.dataset.scalingTab;state.scalingTabs[card.dataset.scalingService]=name;$$('[data-scaling-tab]',card).forEach(item=>item.classList.toggle('active',item.dataset.scalingTab===name));$$('[data-scaling-panel]',card).forEach(panel=>panel.classList.toggle('panel-hidden',panel.dataset.scalingPanel!==name))}))}
function scalingPayload(row,service){const value=name=>$(`[data-scale-field="${name}"]`,row).value;return{name:service.name,service_type:service.service_type,capacity_per_replica:Number(value('capacity_per_replica')),autoscaling_enabled:$('[data-scale-enabled]',row).checked,min_replicas:Number(value('min_replicas')),max_replicas:Number(value('max_replicas')),scale_up_threshold_percent:Number(value('scale_up_threshold_percent')),scale_down_threshold_percent:Number(value('scale_down_threshold_percent')),window_seconds:Number(value('window_seconds')),cooldown_seconds:Number(value('cooldown_seconds')),report_stale_seconds:Number(value('report_stale_seconds')),scale_up_step:service.scale_up_step,failover_replicas:Number(value('failover_replicas')),provider:'acs_kubernetes',namespace:value('namespace'),workload_kind:value('workload_kind'),workload_name:value('workload_name'),acs_container_name:value('acs_container_name')}}
async function saveScaling(row){const service=state.scalingServices.find(item=>item.id===row.dataset.scalingService);if(!service)return;try{await api(`/scaling/services/${service.id}`,{method:'PUT',body:JSON.stringify(scalingPayload(row,service))});toast('混合云伸缩策略已保存');loadScaling()}catch(err){toast(err.message)}}
async function rotateScalingToken(row){const service=state.scalingServices.find(item=>item.id===row.dataset.scalingService);if(!service||!window.confirm(`轮换 ${service.name} 的上报令牌？旧令牌会立即失效。`))return;try{const result=await api(`/scaling/services/${service.id}/report-token/rotate`,{method:'POST'});window.prompt('新上报令牌（仅显示这一次），请立即保存：',result.report_token);toast('上报令牌已轮换')}catch(err){toast(err.message)}}
async function saveInstanceCapacity(row){const raw=$('[data-instance-capacity]',row).value.trim();try{await api(`/scaling/instances/${row.dataset.scalingInstance}/capacity`,{method:'PUT',body:JSON.stringify({capacity_limit:raw?Number(raw):null})});toast('实例业务上限已保存');loadScaling()}catch(err){toast(err.message)}}
function bindScalingInstanceMonitoring(root){const instances=state.scalingServices.flatMap(service=>service.instances||[]);$$('[data-scaling-instance]',root).forEach(row=>{const instance=instances.find(item=>item.id===row.dataset.scalingInstance);if(!instance)return;row.classList.toggle('ignored',!instance.monitored);const button=document.createElement('button');button.textContent=instance.monitored?'忽略':'恢复';button.addEventListener('click',async()=>{if(instance.monitored&&!window.confirm('忽略后，该实例离线或异常将不再触发 ACS 故障兜底。确认继续？'))return;try{await api(`/scaling/instances/${instance.id}/monitoring`,{method:'PUT',body:JSON.stringify({monitored:!instance.monitored})});toast(instance.monitored?'已忽略该实例':'已恢复实例监控');loadScaling()}catch(err){toast(err.message)}});row.append(button)})}
function bindScalingInstanceDeletion(root){const instances=state.scalingServices.flatMap(service=>service.instances||[]);$$('[data-delete-instance]',root).forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('[data-scaling-instance]'),instance=instances.find(item=>item.id===row.dataset.scalingInstance);if(!instance)return;if(!window.confirm(`确认删除实例“${instance.instance_id}”？\n\n删除后会立即从路由与伸缩统计中移除；如果应用仍使用这个 ID 上报，实例会被重新创建。`))return;button.disabled=true;try{await api(`/scaling/instances/${instance.id}`,{method:'DELETE'});toast('错误实例已删除');loadScaling()}catch(err){toast(err.message);button.disabled=false}}))}
const releaseStatusNames={idle:'尚未发布',preparing_acs:'准备 ACS 保护副本',waiting_acs:'等待 ACS 新版本 Ready',updating_local:'逐个更新本地实例',verifying_local:'验证本地实例业务就绪',completed:'版本已统一',failed:'发布已停止'};
function bindScalingReleases(root){$$('[data-scaling-service]',root).forEach(row=>{const service=state.scalingServices.find(item=>item.id===row.dataset.scalingService);if(!service)return;const policy=$('.scaling-policy',row),acsLabel=document.createElement('label');acsLabel.textContent='ACS 目标容器名';acsLabel.innerHTML+=`<input data-scale-field="acs_container_name" value="${esc(service.acs_container_name||'')}" placeholder="多容器 Pod 时必填">`;policy.insertBefore(acsLabel,$('.scaling-checkbox',policy));const section=document.createElement('section'),active=(state.scalingTabs[service.id]||'summary')==='release';section.className=`scaling-card-panel module-release ${active?'':'panel-hidden'} ${service.release_status==='failed'?'failed':''}`;section.dataset.scalingPanel='release';section.innerHTML=`<div><strong>模块期望镜像</strong><span>${esc(releaseStatusNames[service.release_status]||service.release_status)}${service.release_error?` · ${esc(service.release_error)}`:''}</span></div><code>${esc(service.desired_image||'尚未配置')}</code><div class="module-release-actions"><input data-release-image value="${esc(service.desired_image||'')}" placeholder="registry.example/team/model:2.0"><button data-start-release>分阶段发布</button>${service.previous_image?'<button data-rollback-release>回滚上一版</button>':''}</div>`;row.append(section);$('[data-start-release]',section).addEventListener('click',async()=>{const target=$('[data-release-image]',section).value.trim();if(!target||!window.confirm(`确认将 ${service.name} 分阶段发布到：\n${target}\n\nACS 先更新；本地容器严格逐个替换，每个恢复健康上报后才继续。`))return;try{await api(`/scaling/services/${service.id}/release`,{method:'POST',body:JSON.stringify({target_image:target})});toast('分阶段发布已启动');loadScaling()}catch(err){toast(err.message)}});const rollback=$('[data-rollback-release]',section);if(rollback)rollback.addEventListener('click',async()=>{if(!window.confirm(`确认回滚 ${service.name} 到 ${service.previous_image}？`))return;try{await api(`/scaling/services/${service.id}/release/rollback`,{method:'POST'});toast('分阶段回滚已启动');loadScaling()}catch(err){toast(err.message)}})})}
$('#add-scaling-service').addEventListener('click',()=>{$('#scaling-form').reset();$('#scaling-form-fields').classList.remove('hidden');$('#scaling-token-result').classList.add('hidden');$('#scaling-form-error').textContent='';$('#scaling-dialog').classList.remove('hidden')});$$('[data-close-scaling]').forEach(button=>button.addEventListener('click',()=>$('#scaling-dialog').classList.add('hidden')));$('#refresh-scaling').addEventListener('click',loadScaling);
$('#scaling-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form)),numeric=['capacity_per_replica','min_replicas','max_replicas','failover_replicas','scale_up_threshold_percent','scale_down_threshold_percent','window_seconds','cooldown_seconds','report_stale_seconds'];numeric.forEach(key=>data[key]=Number(data[key]));data.autoscaling_enabled=form.elements.autoscaling_enabled.checked;data.scale_up_step=1;data.provider='acs_kubernetes';const button=$('button[type="submit"]',form);button.disabled=true;try{const created=await api('/scaling/services',{method:'POST',body:JSON.stringify(data)});$('#scaling-form-fields').classList.add('hidden');$('#scaling-token-result').classList.remove('hidden');$('#scaling-service-id-result').textContent=created.id;$('#scaling-token-value').textContent=created.report_token;loadScaling()}catch(err){$('#scaling-form-error').textContent=err.message}finally{button.disabled=false}});
setInterval(()=>{if(state.user&&!document.hidden)refreshAll()},15000);restore();
